namespace OpenTPW;

/// <summary>
/// Approximation register of the guests' core decisions (docs/GUESTS.md "Decision", "Needs", docs/reverse/ORACLE.md F24..F26). Each entry is
/// tagged <c>[APPROX:GUEST-NNN]</c> at its code site; the rules themselves are executed in the PowerPC oracle.
/// </summary>
public static class GuestApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("GUEST-002", "BACK CELL AND QUEUE: the attraction's back-of-queue cell (0xDD3F4) is the bridge's last queue cell and its queue count the guests in OpenTPW's queue list; candidates run in attraction-id order, not the original's thing-list order (oracle F24)"),
		("GUEST-003", "PRICE: the original's price test at the stand point is applied (tp.exe 0x4FDE50); its per-type park word is taken as 0 and the refusal's animation, event record, walk-away count and price statistic are not modelled"),
		("GUEST-004", "FULL QUEUE ROOM: a physically full queue (count at 4 per cell) refuses like the queue-too-long case for thought and happiness but pushes no history; its original path is the dismissal 0xEE804 (oracle F24)"),
		("GUEST-005", "USE EFFECTS AND LITTER: a visit fills the litter meter, a relief visit wears the toilet, empties the toilet meter and clears illness above 90 (tp.exe 0x4FE1E0), and a full meter goes to a bin within reach or onto the cell (0x4FEC90, 0x500DC0, 0x4FFF20), but the visit's guest records and the ingredient and appearance effects beyond the speed boost are not modelled, a bin's access cell is its entrance's outside cell or first path neighbour, and a bin removed during the walk counts as none"),
		("GUEST-006", "ENVIRONMENT AND THOUGHTS: the guest's cell environment record has all the original's sources (vomit, stinkbombs, entertainers, guards, toilets, cameras, fireworks; ParkEnvironment) and the thoughts follow tp.exe (the pick 0x4FC8A0 on one needs phase in ten, the setters of 0x50BE80, the bubble's 12 turns and its cooldown by priority), but a load puts back the row an object's saved state implies, a show loses its row when its script's VAR_STATUS reaches 1, which only the script writes in OpenTPW, the pick's one-in-ten draw is a hash of the guest and the turn rather than a draw of the world generator, and bubbles are always on where the original skips them online and while bits 0x16 of the flag word 0x790AB0 are set"),
		("GUEST-007", "PRANKS: pranksters prank as in tp.exe (0x4FF0F5, x86 X18) and a prank on a cell with security sends a guard (0x508A30); a balloon prankster's victim is the first other guest on the cell in OpenTPW's guest order rather than the cell's thing list; the prank message reaches no advisor line and the guest event 15 is not recorded; a guest the guard sets down stands at its own offset and walks to the nearer arrival lane rather than the gate cell its draw picked"),
		("GUEST-008", "ENERGY: OpenTPW's energy meter has no original counterpart (the original has no energy field and nothing here reads it); its drain and recovery rates are invented"),
		("GUEST-009", "BOREDOM: a guest whose last ride lies more than its type's BoredomThreshold seconds back loses SmallHappinessChange at each major decision; tp.exe loads BoredomThreshold as field 6 of the PeepTypes record, but its reader is not located"),
		("GUEST-010", "STATES 6 AND 7: OpenTPW runs the original's decision state and wander walk (x86 X18, X19) (the litter step and the vomit's litter since ORACLE.md 7.15) without the presentation turns towards shows and performers, the walk's stuck result, the off-path destination search and the stranded mark; the leaving gate's route test asks for a path to an arrival lane's end (none: the guest leaves when the park has no lanes), and a step's candidates are the current cell's links to path cells (the original removes only queue and type-10 neighbours)"),
		("GUEST-011", "CLOSURE: OpenTPW pulls guests out of queues and drops GoingToRide reservations when the park closes; in the original no queue state and no ride routine reads the closed word (tp.exe), so its queues keep running, while state 10 (going to a ride) does drop the reservation"),
		("GUEST-012", "STATE-18 RECALL: the leaving handler's recall (0xedc98) also demands the guest's cell pass 0xe6c6c (its cell record through 0x10a9b0 and 0x85190..0x851d0), which is untraced; OpenTPW approximates the predicate by the state boundary — only a guest still walking the paths to the exit recalls, and the road ends it (the booth refusal enters on a lane and is exempt, like the original's zeroed counter 0xecacc) (oracle F26)"),
		("GUEST-013", "STAFF DROP CELLS: the original refuses a cell whose structure record (+0 -> table at 0x8023a0 + 0x10ffd8) is of kind 0xb, 0xd, 0x10, 0x12 or 0x19 (following 0xc and 0x11 to the parent record), most likely ride, shop and scenery footprints; OpenTPW refuses every cell under a placed object or the prototype ride (evidence needed: the structure-record kinds)"),
		("GUEST-014", "STAFF SPRITE BANK: the original's variant byte (candidate +9, member +0x20) is not part of OpenTPW's staff records and the order of the banks it indexes is untraced: the bank is (NameIndex + Id) modulo the folder's banks in file order (evidence needed: the candidate's variant byte and the bank order of 0x4d4140)"),
		("GUEST-015", "ENTERTAINER PERFORMANCES: an entertainer performs a random one of the scripts 13-16 whose entries (0-3) the original resolves per bank (0x540c70, untraced); OpenTPW picks per member one of the bank's multi-frame slots 4, 10, 3, 11, while it performs, state 14 (evidence needed: the per-bank resolution 0x540c70)"),
		("GUEST-016", "STAFF ANIMATION TIMING: the clips run at 10 frames a second (half rate 5), a member counts as moving after a position change within 0.6 s (1.3 s for members the world moves a cell a second), the drawn position is smoothed and the heading comes from the position change, instead of the original's per-turn animation steps (0x4d4190) and movement vectors (evidence needed: the script player's frame timing)"),
		("GUEST-920", "Visitor elapsed simulation seconds start at successful admission or zero for seeded guests; the admission tick and travel home are excluded, and native timing is untraced"),
	};
}
